select tpmr.test_project_member_role_id as testProjectMemberRoleId, tpmr.role_key as roleKey, tpmr.role_name as roleName, tpmr.sort_num as sortNum, tpmr.enable_status as enableStatus, tpmr.remark as remark, tpmr.del_status as delStatus, tpmr.create_time as createTime, tpmr.update_time as updateTime from test_project_member_role tpmr where tpmr.del_status = 0
and tpmr.role_key = #{roleKey}
and tpmr.role_name like concat('%', #{roleName}, '%')
and tpmr.sort_num = #{sortNum}
and tpmr.enable_status = #{enableStatus}
order by tpmr.test_project_member_role_id desc

select count(1)
from test_project_member_role tpmr
where tpmr.del_status = 0

    and tpmr.role_key = #{roleKey}


    and tpmr.role_name like concat('%', #{roleName}, '%')


    and tpmr.sort_num = #{sortNum}


    and tpmr.enable_status = #{enableStatus}

select tpmr.test_project_member_role_id, tpmr.role_key, tpmr.role_name, tpmr.sort_num, tpmr.enable_status, tpmr.remark, tpmr.del_status, tpmr.create_time, tpmr.update_time from test_project_member_role tpmr where tpmr.del_status = 0
